const cases={ru:{file:'content/pages/ru/otzyvy.json',pk:'отзывы о GPTBot',sk:['кейсы AI-ботов','сценарии автоматизации заявок','как проверить чат-бота'],h1:'Отзывы и кейсы GPTBot.uz: как проверяем результаты',title:'Отзывы и кейсы GPTBot.uz — сценарии AI-ботов',desc:'Отзывы GPTBot.uz публикуются только с разрешением клиента. Ниже — обезличенные сценарии AI-ботов, критерии приёмки и метрики результата.',hero:'Отзывы и кейсы GPTBot.uz без выдуманных рейтингов',sub:'Публичные именные отзывы размещаем только с разрешением. Пока здесь обезличенные составные сценарии; эффект проверяется по событиям воронки и данным CRM.',head:['Ниша','Исходная задача','Роль бота','Что измерять'],rows:[['Клиника','Обращения вечером','Ответ, услуга, контакт, передача','Время ответа и запись'],['Салон','Direct без структуры','Услуга, филиал, время, контакт','Диалоги и подтверждённые записи'],['Учебный центр','Много вопросов','Курс, уровень, филиал, пробный урок','Квалифицированные заявки'],['Магазин','Товар и доставка','Каталог, состав заказа, эскалация','Точность и подтверждённые заказы'],['Недвижимость','Нет бюджета и района','Бюджет, район, объект, срок','Полнота карточки и показы']],facts:['Это составные сценарии, а не дословные отзывы конкретных клиентов.','Клик по контакту не равен квалифицированному лиду, а заявка — продаже.','До запуска фиксируется baseline; после запуска сравниваются одинаковые этапы и периоды.','Интеграция принимается по тестам доставки, дублей, ошибок и восстановления.'],proof:['Демо с корректным ответом и честным отказом.','Источники знаний и правило обновления цен и условий.','Карта данных: поля, получатели и доступы.','Критерии приёмки, включая недоступность CRM и эскалацию человеку.','Определение событий: контакт, заявка, квалификация и продажа.'],faq:[['Это реальные отзывы клиентов?','Нет. Здесь обезличенные составные сценарии. Именной отзыв, рейтинг или результат публикуется только после подтверждения источника и разрешения клиента.'],['Какие метрики показывают пользу AI-бота?','Время ответа, завершение сценария, полнота полей, квалифицированные заявки, ошибки и ручные исправления. Продажи считаются отдельно по CRM.'],['Можно ли посмотреть сценарий для моей ниши?','Да. Подготовим демонстрационный маршрут, вопросы, точки передачи менеджеру и критерии проверки без реальных заявок.']]},uz:{file:'content/pages/uz/sharhlar.json',pk:'GPTBot sharhlari',sk:['AI-bot keyslari','murojaatlarni avtomatlashtirish','chat-botni tekshirish'],h1:'GPTBot.uz sharhlari va keyslari: natijani qanday tekshiramiz',title:'GPTBot.uz sharhlari va AI-bot keyslari',desc:'GPTBot.uz sharhlari faqat mijoz ruxsati bilan e’lon qilinadi. Quyida anonim AI-bot ssenariylari, qabul mezonlari va natija metrikalari.',hero:'GPTBot.uz sharhlari va keyslari — o‘ylab topilgan reytingsiz',sub:'Ismli sharh faqat mijoz ruxsati bilan joylanadi. Hozir anonim tarkibiy ssenariylar bor; ta’sir voronka hodisalari va CRM ma’lumoti bilan tekshiriladi.',head:['Soha','Boshlang‘ich vazifa','Bot roli','Nimani o‘lchash'],rows:[['Klinika','Kechki murojaat','Javob, xizmat, kontakt, uzatish','Javob vaqti va yozuv'],['Salon','Direct tartibsiz','Xizmat, filial, vaqt, kontakt','Dialog va tasdiqlangan yozuv'],['O‘quv markazi','Ko‘p savol','Kurs, daraja, filial, sinov darsi','Malakali ariza'],['Do‘kon','Tovar va yetkazish','Katalog, buyurtma, eskalatsiya','Aniqlik va tasdiqlangan buyurtma'],['Ko‘chmas mulk','Byudjet va tuman yo‘q','Byudjet, tuman, obyekt, muddat','Kartochka va ko‘rik']],facts:['Bular aniq mijozning so‘zma-so‘z sharhi emas, anonim tarkibiy ssenariylar.','Kontaktga bosish malakali lid emas, ariza esa sotuv emas.','Oldin baseline qayd etiladi; keyin bir xil bosqich va davr solishtiriladi.','Integratsiya yetkazish, dubl, xato va tiklash sinovlari bilan qabul qilinadi.'],proof:['To‘g‘ri javob va halol rad etish bilan demo.','Bilim manbalari va yangilash qoidasi.','Ma’lumot xaritasi: maydon, qabul qiluvchi va kirish.','CRM ishlamasligi va insonga eskalatsiya qabul mezonida.','Hodisalar: kontakt, ariza, malaka va sotuv.'],faq:[['Bular real mijozlar sharhlarimi?','Yo‘q. Bu anonim tarkibiy ssenariylar. Ism, reyting yoki natija faqat manba va mijoz ruxsati bo‘lsa e’lon qilinadi.'],['AI-bot foydasini qaysi metrikalar ko‘rsatadi?','Javob vaqti, ssenariy yakuni, maydon to‘liqligi, malakali ariza, xato va qo‘lda tuzatish. Sotuv CRM bo‘yicha hisoblanadi.'],['Soham uchun ssenariyni ko‘rish mumkinmi?','Ha. Haqiqiy arizasiz demo yo‘li, savollar, menejerga uzatish va tekshiruv mezonlarini tayyorlaymiz.']]}};
function rewriteCase(lang){const c=cases[lang],p=rd(c.file);Object.assign(p,{primaryKeyword:c.pk,secondaryKeywords:c.sk,h1:c.h1,title:c.title,description:c.desc,heroTitle:c.hero,heroSubtitle:c.sub,breadcrumbLabel:lang==='ru'?'Отзывы и кейсы':'Sharhlar va keyslar'});p.bodyBlocks=[{type:'p',text:lang==='ru'?'Мы не публикуем именные отзывы, оценки или цифры без проверяемого источника и разрешения клиента.':'Tekshiriladigan manba va mijoz ruxsatisiz ism, baho yoki raqam e’lon qilinmaydi.'},{type:'h2',text:lang==='ru'?'Сценарии по нишам':'Sohalar bo‘yicha ssenariylar'},{type:'table',headers:c.head,rows:c.rows},{type:'h2',text:lang==='ru'?'Как читать эти кейсы':'Bu keyslarni qanday o‘qish kerak'},{type:'list',items:c.facts},{type:'h2',text:lang==='ru'?'Какие доказательства запросить до покупки':'Xariddan oldin qaysi dalillarni so‘rash kerak'},{type:'list',items:c.proof},{type:'cta',text:lang==='ru'?'Получить сценарий и критерии приёмки':'Ssenariy va qabul mezonlarini olish',href:'https://t.me/XGame_changerx'}];p.faq=c.faq.map(([q,a])=>({q,a}));p.schemaTypes=['Organization','WebSite','BreadcrumbList','FAQPage'];wr(c.file,touch(p))}

function pricing(f,lang){const p=rd(f),ru=lang==='ru';Object.assign(p,{title:ru?'Стоимость чат-бота: тарифы и состав работ | GPTBot':'Chat-bot narxi: tariflar va ish tarkibi | GPTBot',description:ru?'Ориентиры по стоимости чат-бота: Telegram-бот от 990 000 сум. Итоговая смета зависит от сценариев, каналов, CRM, нагрузки и поддержки.':'Chat-bot narxi: Telegram-bot 990 000 so‘mdan. Yakuniy smeta ssenariy, kanal, CRM, yuklama va qo‘llab-quvvatlashga bog‘liq.'});for(const b of p.bodyBlocks)if(b.type==='p'){if(ru&&(b.text||'').startsWith('Коротко: чат-бот'))b.text='Коротко: базовый Telegram-бот начинается от 990 000 сум, Instagram Direct бот — от 1 190 000 сум, базовая AI-воронка — от 1 990 000 сум. Это стартовые цены для указанного состава, а не обещание полной системы.';if(!ru&&(b.text||'').startsWith('Qisqacha: O‘zbekiston'))b.text='Qisqacha: bazaviy Telegram-bot 990 000 so‘mdan, Instagram Direct bot 1 190 000 so‘mdan, AI-voronka 1 990 000 so‘mdan. Bu ko‘rsatilgan tarkib uchun boshlang‘ich narx.';if(ru&&/Чат-бот окупается за счёт заявок/i.test(b.text||''))b.text='Окупаемость не гарантируется ценой бота. До запуска фиксируют baseline: обращения, время ответа, квалифицированные заявки, продажи и стоимость ручной обработки; затем сравнивают одинаковые периоды с учётом поддержки и сервисов.';if(!ru&&/Chat-bot ilgari yo‘qolib ketgan arizalar hisobiga qoplanadi/i.test(b.text||''))b.text='Bot narxi qoplanishni kafolatlamaydi. Oldin murojaat, javob vaqti, malakali ariza, sotuv va qo‘lda ishlash xarajati qayd etiladi; keyin bir xil davrlar solishtiriladi.'}p.bodyBlocks=p.bodyBlocks.filter(b=>!/По рынку Ташкента цены стартуют примерно от 3 млн|25 млн сум|Toshkent bozorida narxlar taxminan 3 mln|25 mln so‘m/i.test(txt(b)));before(p.bodyBlocks,ru?'Таблица тарифов на чат-бота 2026':'Chat-bot tariflari jadvali 2026',[{type:'h2',text:ru?'Как читать цену «от»':'“Dan boshlab” narxini qanday o‘qish kerak'},{type:'list',items:ru?['Цена относится только к указанному составу.','Дополнительные каналы, CRM, оплата, каталог и миграция считаются отдельно.','Платформенные тарифы, AI-модель и лицензии указываются отдельно.','Изменение scope оформляется обновлённой сметой.']:['Narx faqat ko‘rsatilgan tarkibga tegishli.','Qo‘shimcha kanal, CRM, to‘lov, katalog va migratsiya alohida.','Platforma tarifi, AI-model va litsenziya alohida.','Scope o‘zgarishi yangilangan smeta bilan.']}]);p.faq||=[];p.faq.splice(1,0,ru?{q:'Что означает цена «от»?',a:'Это минимальная стоимость пакета с указанным составом. Дополнительные каналы, CRM, оплата, нагрузка и поддержка добавляются отдельно.'}:{q:'“Dan boshlab” narxi nimani anglatadi?',a:'Bu ko‘rsatilgan tarkibdagi paketning eng past narxi. Qo‘shimcha kanal, CRM, to‘lov, yuklama va qo‘llab-quvvatlash alohida.'});wr(f,touch(p))}

function crm(f,lang){let p=rd(f),ru=lang==='ru';Object.assign(p,{title:ru?'AI-бот с AmoCRM и Bitrix24: передача лидов | GPTBot':'AmoCRM va Bitrix24 bilan AI-bot: lid uzatish | GPTBot',description:ru?'AI-бот собирает данные и передаёт лид в AmoCRM или Bitrix24. Scope: поля, дедупликация, повторы, мониторинг и восстановление.':'AI-bot ma’lumot yig‘ib, lidni AmoCRM yoki Bitrix24’ga uzatadi. Scope: maydon, deduplikatsiya, qayta urinish, monitoring va tiklash.'});before(p.bodyBlocks,ru?'Ограничения и риски, которые важно понимать':'Tushunish muhim bo‘lgan cheklovlar va xavflar',[{type:'h2',text:ru?'Надёжность передачи: критерии приёмки':'Uzatish ishonchliligi: qabul mezonlari'},{type:'table',headers:ru?['Контроль','Критерий']:['Nazorat','Mezon'],rows:ru?[['Подтверждение','Успех только после ответа API'],['Повторные попытки','Интервал и предел без бесконечного цикла'],['Идемпотентность','Повтор не создаёт вторую сделку'],['Дедупликация','Конфликт уходит на ручную проверку'],['Мониторинг','Ошибка видна до жалобы клиента'],['Восстановление','Безопасный ручной replay']]:[['Tasdiq','Muvaffaqiyat faqat API javobidan keyin'],['Qayta urinish','Interval va limit'],['Idempotentlik','Takror ikkinchi bitim yaratmaydi'],['Deduplikatsiya','Nizo qo‘lda tekshiriladi'],['Monitoring','Xato shikoyatdan oldin ko‘rinadi'],['Tiklash','Xavfsiz qo‘lda replay']]},{type:'p',text:ru?'Недоступность API или лимит CRM может задержать передачу; нужен видимый статус и ручной маршрут.':'API ishlamasligi yoki CRM limiti uzatishni kechiktirishi mumkin; ko‘rinadigan status va qo‘lda yo‘l kerak.'}]);let s=JSON.stringify(p);for(const [a,b] of (ru?[['чтобы ни одно обращение не потерялось','чтобы снизить риск потери обращения'],['лиды больше не теряются','снижается риск потери лидов'],['без дублей','с проверкой возможных дублей']]:[['dublikatlarsiz','ehtimoliy dublikatlarni tekshirish bilan']]))s=s.replaceAll(a,b);wr(f,touch(JSON.parse(s)))}

